    if (res.year < 1000 || res.year > 9999) {
      throw new RangeError('Year out of bounds');
    }
    return res.str;
  }

  const steps = Math.abs(n);
  const dir = n > 0 ? 1 : -1;

  // Let's optimize large n or implement step by step efficiently.
  // Since n can be up to 100000, step by step (100000 iterations) takes < 5-10ms in Node.js.
  // But let's be careful about step definition:
  // "Each step moves one calendar day forward (if n is positive) or backward (if n is negative), 
  //  and then keeps moving in the same direction until it lands on a weekday (Monday to Friday)."

  for (let i = 0; i < steps; i++) {
    currentDays += dir;
    let dow = getDayOfWeek(currentDays);
    // If it's Saturday (6) or Sunday (0), keep moving in the same direction until weekday (1-5)
    while (dow === 0 || dow === 6) {
      currentDays += dir;
      dow = getDayOfWeek(currentDays);
    }
  }

  const finalDate = daysToDate(currentDays);
  if (finalDate.year < 1000 || finalDate.year > 9999) {
    throw new RangeError('Year out of bounds');
  }

  return finalDate.str;
}

