const test = require('node:test');
const assert = require('node:assert/strict');
const { addBusinessDays } = require('./bizdays');

test('within a week', () => {
  assert.equal(addBusinessDays('2024-01-01', 2), '2024-01-03');
});

test('over a weekend', () => {
  assert.equal(addBusinessDays('2024-01-05', 1), '2024-01-08');
});

test('zero business days', () => {
  assert.equal(addBusinessDays('2024-01-01', 0), '2024-01-01');
  assert.equal(addBusinessDays('2024-01-06', 0), '2024-01-06'); // Saturday
});

test('negative business days', () => {
  assert.equal(addBusinessDays('2024-01-03', -2), '2024-01-01');
  assert.equal(addBusinessDays('2024-01-08', -1), '2024-01-05');
  assert.equal(addBusinessDays('2024-01-01', -1), '2023-12-29'); // Friday before Monday
});

test('type and range errors', () => {
  assert.throws(() => addBusinessDays(123, 1), TypeError);
  assert.throws(() => addBusinessDays(null, 1), TypeError);
  assert.throws(() => addBusinessDays('2024-01-32', 1), RangeError);
  assert.throws(() => addBusinessDays('2024-02-30', 1), RangeError);
  assert.throws(() => addBusinessDays('not-a-date', 1), RangeError);
  assert.throws(() => addBusinessDays('0999-01-01', 1), RangeError);
  assert.throws(() => addBusinessDays('2024-01-01', 1.5), RangeError);
  assert.throws(() => addBusinessDays('2024-01-01', Number.MAX_SAFE_INTEGER + 1), RangeError);
});
`}
